{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin absolute oral bioavailability was 91.2% in healthy subjects after 0.6 mg tablets in the fasting state, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Lefamulin absolute oral bioavailability was 25.8% in fasted healthy adults after a 600 mg immediate-release oral dose, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Danazol absolute oral bioavailability was 11 ± 5.2% in fasted human subjects after a 100 mg oral solution, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer human absolute bioavailability records support F ≥ 20% (digitoxin 91%, lefamulin 25.8%, perindopril ~75%, UDCA 50%, ethinylestradiol ~40-54%, β-methyldigoxin ~59-76%). One fasted danazol record is below threshold, but the larger set of direct positive measurements supports high.",
  "evidence_gaps": [
    "Molecule 2 groups different compounds (Uniphyl, amphotericin B, posaconazole, voriconazole); inconsistent cards were discounted.",
    "Molecule 5 has mixed tacrolimus bioavailability records (14% in one healthy-volunteer study vs mean 20-25% in others), leaving direction uncertain.",
    "Molecule 3's negative record is for S-9780/perindoprilat after perindopril, not clearly the parent absolute oral bioavailability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

